shellCommands.command:
/bin/bash -lc "cat > /tmp/catalog-prefetch-check/check.mjs <<'EOF'
import assert from 'node:assert/strict'
import { chromium } from './node_modules/playwright/index.mjs'

const browser = await chromium.launch({ headless: true })
const context = await browser.newContext()
const page = await context.newPage()
const prefetches = []
const responseTasks = []
const errors = []
page.on('pageerror', (error) => errors.push(error.message))
page.on('response', (response) => {
  const request = response.request()
  if (request.url().includes('/catalog') && request.headers()['next-router-prefetch']) {
    responseTasks.push(response.text().then((body) => {
      prefetches.push({ url: request.url(), body })
    }))
  }
})

try {
  await page.goto('http://127.0.0.1:3000/')
  await page.waitForLoadState('networkidle')
  await Promise.all(responseTasks)
  for (const [category, heading, products] of [
    ['featured', 'Featured products', ['Desk Lamp', 'Wool Blanket']],
    ['sale', 'Products on sale', ['Canvas Tote', 'Travel Mug']],
  ]) {
    const payload = prefetches.filter(({ url }) => new URL(url).searchParams.get('category') === category).map(({ body }) => body).join('\\n')
    assert.ok(payload.includes(heading), "'`${category}: heading was prefetched`)
    for (const product of products) assert.ok(payload.includes(product), `${category}: ${product} was prefetched`)
  }
  console.log('"'Both category URLs prefetched their own headings and products before any click.')

  await context.setOffline(true)
  await page.evaluate(() => {
    window.loadingStateSeen = false
    new MutationObserver((mutations) => {
      if (document.body.innerText.includes('Loading category...') || mutations.some((mutation) => [...mutation.addedNodes].some((node) => node.textContent?.includes('Loading category...')))) {
        window.loadingStateSeen = true
      }
    }).observe(document.body, { subtree: true, childList: true, characterData: true })
  })
  for (const [category, heading, products] of [
    ['featured', 'Featured products', ['Desk Lamp', 'Wool Blanket']],
    ['sale', 'Products on sale', ['Canvas Tote', 'Travel Mug']],
  ]) {
    const start = Date.now()
    await page.locator("'`a[href="/catalog?category=${category}"]`).click()
    await page.waitForURL(`**/catalog?category=${category}`, { timeout: 2000 })
    await page.getByRole('"'heading', { name: heading, exact: true }).waitFor({ timeout: 2000 })
    assert.deepEqual(await page.locator('section li').allTextContents(), products)
    assert.equal(await page.evaluate(() => window.loadingStateSeen), false, 'Loading fallback never appeared')
    console.log("'`${category}: correct heading and products rendered offline in ${Date.now() - start}ms, without the loading state.`)
    await page.goBack()
    await page.getByRole('"'heading', { name: 'Shop by category' }).waitFor()
  }
  assert.deepEqual(errors, [])
} finally {
  await browser.close()
}
EOF"
